import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Lazy;
import me.zodac.folding.rest.RequiredRoles;

import me.zodac.folding.api.tc.validation.ValidationFailureType;
import me.zodac.folding.rest.response.Responses;
import me.zodac.folding.api.tc.validation.ValidationResult;


public final class ValidationFailureResponseMapper {

    private ValidationFailureResponseMapper() {

    }


    public static ResponseEntity<String> map(final ValidationResult<?> validationResult) {
        switch (validationResult.getValidationFailureType()) {
            case BAD_REQUEST:
                return Responses.badRequest(validationResult.getValidationFailure());
            case CONFLICT:
                return Responses.conflict(validationResult.getValidationFailure());
            case NONE:
            default:
                throw new IllegalStateException(String.format("Cannot map a REST response for validation result: %s", validationResult));
        }
    }
}
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Lazy;
import org.springframework.scheduling.annotation.Async;

import static java.lang.Boolean.parseBoolean;

import me.zodac.folding.state.ParsingStateManager;
import me.zodac.folding.state.SystemStateManager;
import me.zodac.folding.api.state.ParsingState;
import me.zodac.folding.api.state.SystemState;
import me.zodac.folding.api.util.EnvironmentVariableUtils;
import me.zodac.folding.service.tc.user.UserStatsResetter;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

@Service
public class StartOfMonthScheduler {

    private static final Logger LOGGER = LogManager.getLogger();
    private static final boolean IS_MONTHLY_RESET_ENABLED =
        parseBoolean(EnvironmentVariableUtils.getOrDefault("ENABLE_STATS_MONTHLY_RESET", "false"));
    private static final String STATS_PARSING_SCHEDULE_FIRST_DAY_OF_MONTH =
        EnvironmentVariableUtils.getOrDefault("STATS_PARSING_SCHEDULE_FIRST_DAY_OF_MONTH", "3");

    @Autowired
    @Lazy
    private UserStatsResetter userStatsResetter;


    @org.springframework.scheduling.annotation.Scheduled(cron = "0 15 0 ${STATS_PARSING_SCHEDULE_FIRST_DAY_OF_MONTH:3} * *", zone = "UTC")
    public void startOfTeamCompetition() {
        if (!IS_MONTHLY_RESET_ENABLED) return;
        try {

            LOGGER.warn("Starting TC stats for new month");

            SystemStateManager.next(SystemState.RESETTING_STATS);
            ParsingStateManager.next(ParsingState.DISABLED);
            userStatsResetter.resetTeamCompetitionStats();
            SystemStateManager.next(SystemState.WRITE_EXECUTED);
        } catch (final Exception e) {
            LOGGER.error("Error with start of team schedule", e);
        }
    }
}

